commands.stdout_excerpt:
                   "type": "array",
                    "items": {
                        "type": "object",
                        "additionalProperties": false,
                        "required": [
                            "path",
                            "reason"
                        ],
                        "properties": {
                            "path": {
                                "type": "string"
                            },
                            "reason": {
                                "type": "string"
                            }
                        }
                    }
                },
                "extensions": {
                    "$ref": "#/$defs/extensions"
                }
            }
        },
        "checksums": {
            "type": "object",
            "additionalProperties": false,
            "required": [
                "checksum_manifest_ref",
                "checksum_manifest_path",
                "algorithm",
                "manifest_digest"
            ],
            "properties": {
                "checksum_manifest_ref": {
                    "type": "string"
                },
                "checksum_manifest_path": {
                    "type": "string"
                },
                "algorithm": {
                    "type": "string",
                    "const": "sha256"
                },
                "manifest_digest": {
                    "type": "string",
                    "pattern": "^sha256:[0-9a-f]{64}$"
                },
                "extensions": {
                    "$ref": "#/$defs/extensions"
                }
            }
        },
        "provenance": {
            "type": "object",
            "additionalProperties": false,
            "required": [
                "provenance_ref",
                "provenance_path",
                "preview_only",
                "no_publish",
                "source_repo_local_path_suppressed"
            ],
            "properties": {
                "provenance_ref": {
                    "type": "string"
                },
                "provenance_path": {
                    "type": "string"
                },
                "preview_only": {
                    "type": "boolean"
                },
                "no_publish": {
                    "type": "boolean"
                },
                "source_repo_local_path_suppressed": {
                    "type": "boolean"
                },
                "extensions": {
                    "$ref": "#/$defs/extensions"
                }
            }
        },
        "sbom": {
            "type": "object",
            "additionalProperties": false,
            "required": [
                "sbom_ref",
                "status",
                "reason"
            ],
            "properties": {
                "sbom_ref": {
                    "type": "string"
                },
                "status": {
                    "type": "string"
                },
                "reason": {
                    "type": "string"
                },
                "extensions": {
                    "$ref": "#/$defs/extensions"
                }
            }
        },
        "signature": {
            "type": "object",
            "additionalProperties": false,
            "required": [
                "signature_ref",
                "status",
                "verified",
                "reason"
            ],
            "properties": {
                "signature_ref": {
                    "type": "string"
                },
                "status": {
                    "type": "string"
                },
                "verified": {
                    "type": "boolean"
                },
                "reason": {
                    "type": "string"
                },
                "extensions": {
                    "$ref": "#/$defs/extensions"
                }
            }
        }
    }
}
